import pandas as pd
from datetime import timedelta

def aa():
 d=pd.read_csv('airlines/AA.csv'); d['dt']=pd.to_datetime(d.date+' '+d.sched_dep, errors='coerce'); d['actdt']=pd.to_datetime(d.date+' '+d.actual_dep.fillna(''),errors='coerce'); d['month']=d.dt.dt.strftime('%Y-%m'); d['done']=(d.cancelled==False)&d.actdt.notna(); d['delay']=d.done & ((d.actdt-d.dt).dt.total_seconds()>900); return d

def ass():
 d=pd.read_csv('airlines/AS.csv'); off=pd.read_csv('airports.csv')[['airport','utc_offset_hours']]; d=d.merge(off,left_on='origin',right_on='airport',how='left');
 d['schedutc']=pd.to_datetime(d.date_utc+' '+d.sched_dep_utc,errors='coerce'); d['actutc']=pd.to_datetime(d.date_utc+' '+d.actual_dep_utc.fillna(''),errors='coerce');
 # local conversion by subtract offset
 d['schedlocal']=d.schedutc-pd.to_timedelta(d.utc_offset_hours,unit='h'); d['actlocal']=d.actutc-pd.to_timedelta(d.utc_offset_hours,unit='h'); d['month']=d.schedlocal.dt.strftime('%Y-%m'); d['done']=(d.cancelled==False)&d.actutc.notna(); d['delay']=d.done & ((d.actutc-d.schedutc).dt.total_seconds()>900); return d
A=aa(); S=ass()
for n,d in [('AA',A),('AS',S)]:
 print(n, d.groupby('month')[['done','delay']].sum().to_string()); print('missing offsets',d.utc_offset_hours.isna().sum() if n=='AS' else '')
 print('boundary rows',d[(d.month.isin(['2024-12','2025-01','2025-02','2025-03'])) & (d.done)].sort_values('month').tail(3).to_string())

