import pandas as pd, json
out={'carriers':{},'combined':{}}
for carrier in ['UA','WN']:
 d=pd.read_csv(f'airlines/{carrier}.csv'); d['month']=d.date.str[:7]
 d['smin']=d.sched_dep.str[:2].astype(int)*60+d.sched_dep.str[3:].astype(int)
 d['amin']=pd.to_numeric(d.actual_dep.str[:2],errors='coerce')*60+pd.to_numeric(d.actual_dep.str[3:],errors='coerce')
 d['raw']=d.amin-d.smin
 # Negative differences less than an hour are early departures; very large negative means next calendar day.
 d['delay']=d.raw.where(d.raw>=-60,d.raw+1440)
 out['carriers'][carrier]={}
 for m in ['2025-01','2025-02']:
  x=d[(d.month==m)&(~d.cancelled)&d.actual_dep.notna()]
  out['carriers'][carrier][m]={'completed':len(x),'delayed':int((x.delay>15).sum())}
for m in ['2025-01','2025-02']:
 out['combined'][m]={k:sum(out['carriers'][c][m][k] for c in ['UA','WN']) for k in ['completed','delayed']}
print(json.dumps(out,indent=2))
# show corrected midnight rows and delays >15 perhaps validation
